442	        public async Task<bool> RefreshDiffAsync(string? reason = null)
443	        {
444	            if (_isRefreshing)
445	            {
446	                return false;
447	            }
448	
449	            _isRefreshing = true;
450	            try
451	            {
452	                var trimmedLines = await DiffService.GetPluginsDiffAsync(_mainViewModel.Config);
453	                string newSignature = BuildSignature(trimmedLines);
454	
455	                bool signatureChanged = !string.Equals(newSignature, _lastDiffSignature, StringComparison.Ordinal);
456	                
457	                if (signatureChanged)
458	                {
459	                    var fullLines = await DiffService.GetFullPluginsDiffAsync(_mainViewModel.Config);
460	                    ReplaceDiffLines(fullLines);
461	                    _lastDiffSignature = newSignature;
462	                    DiffStatusMessage = reason ?? Texts.DifferencesLoadedStatus;
463	                    RequestScroll();
464	                }
465	                else
466	                {
467	                    DiffStatusMessage = Texts.NoNewDifferencesStatus;
468	                }
469	
470	                return signatureChanged;
471	            }
472	            catch (Exception ex)
473	            {
474	                DiffStatusMessage = Texts.FailedToRefreshError + " " + ex.Message;
475	                return false;
476	            }
477	            finally
478	            {
479	                _isRefreshing = false;
480	            }
481	        }
