609	        /// <returns>
610	        /// <c>null</c> when only safe change types are present (Added, Replaced, Moved, or
611	        /// Unchanged) — no confirmation dialog is required. A non-<c>null</c> formatted string
612	        /// when at least one <see cref="DiffChangeType.Removed"/> or
