626	
627	            if (removedCount > 0)
628	            {
629	                detailLines.Add(removedCount == 1
630	                    ? Texts.ConfirmRiskyDetail_RemovedSingular
631	                    : string.Format(Texts.ConfirmRiskyDetail_Removals, removedCount));
632	            }
