637	                    ? Texts.ConfirmRiskyDetail_InsertedSingular
638	                    : string.Format(Texts.ConfirmRiskyDetail_Insertions, insertedCount));
639	            }
640	
641	            string detailBlock = string.Join("\n", detailLines);
642	            return string.Format(Texts.ConfirmUpdateMessage_RiskyChanges, detailBlock);
